    else:","+            draw_cross(ax, xc, y_bot - 0.085, NO_EFFECT_DK, size=0.012)"," ","     # Layer labels","-    for ln, label in [(1, 'L1'), (13, 'L13'), (16, 'L16'), (32, 'L32')]:","+    for ln in [1, 13, 16, 32]:","         yy = y_bot + (ln - 0.5) / 32 * (y_top - y_bot)","         c = CAUSAL_RED if ln in (13, 16) else TEXT_LIGHT","         w = 'bold' if ln in (13, 16) else 'normal'","-        ax.text(0.04, yy, label, fontsize=7, color=c, fontweight=w,","+        ax.text(0.03, yy, f'L{ln}', fontsize=6.5, color=c, fontweight=w,","                 transform=ax.transAxes, va='center', ha='right')"," ","-    # Causal window bracket annotation","+    # Causal window bracket","     l13_y = y_bot + (12.5) / 32 * (y_top - y_bot)","     l16_y = y_bot + (15.5) / 32 * (y_top - y_bot)","     mid_y = (l13_y + l16_y) / 2","-    bx = 0.14 + bar_w / 2 + 0.025","-    ax.plot([bx, bx + 0.015, bx + 0.015, bx], [l13_y, l13_y, l16_y, l16_y],","-            color=CAUSAL_RED, lw=1.0, transform=ax.transAxes, zorder=5)","-    ax.text(bx + 0.03, mid_y, 'causal\\nwindow', fontsize=7, color=CAUSAL_RED,","+    bx = 0.12 + bar_w / 2 + 0.02","+    ax.plot([bx, bx + 0.012, bx + 0.012, bx], [l13_y, l13_y, l16_y, l16_y],","+            color=CAUSAL_RED, lw=0.9, transform=ax.transAxes, zorder=5,","+            solid_capstyle='round')","+    ax.text(bx + 0.025, mid_y, 'causal\\nwindow', fontsize=6.5, color=CAUSAL_RED,","             fontweight='bold', transform=ax.transAxes, va='center', ha='left',","             linespacing=1.0)"," ","-    # ATE bars + p-values on the right side","-    ate_x = 0.66","-    ate_max_w = 0.22","+    # ── ATE bars + p-values ──","+    ate_x = 0.60","+    ate_max_w = 0.26","     ate_data = [","         ('L13', 0.42, 'p < 0.001 ***', CAUSAL_RED, True),","         ('L16', 0.28, 'p = 0.005 **', CAUSAL_RED, True),"]},{"oldStart":387,"oldLines":47,"newStart":402,"newLines":41,"lines":["     ]"," ","     bar_spacing = 0.065","-    ate_top = 0.78","+    ate_top = 0.80","     for i, (layer, effect, pval, color, sig) in enumerate(ate_data):","         yy = ate_top - i * bar_spacing","-        bw = effect / 0.45 * ate_max_w","-        bh = 0.025","+        bw = max(effect / 0.45 * ate_max_w, 0.012)","+        bh = 0.022"," ","-        # Layer label","-        ax.text(ate_x - 0.03, yy, layer, fontsize=7.5, color=color,","+        ax.text(ate_x - 0.02, yy, layer, fontsize=7.5, color=color,","                 fontweight='bold' if sig else 'normal',","                 transform=ax.transAxes, va='center', ha='right')"," ","-        # Bar","         rbox(ax, ate_x, yy - bh / 2, bw, bh,","              fc=color, ec='none', lw=0, rad=bh / 2,","              alpha=0.85 if sig else 0.30, zorder=3)"," ","-        # p-value","-        ax.text(ate_x + bw + 0.015, yy, pval,","+        ax.text(ate_x + bw + 0.012, yy, pval,","                 fontsize=6.5, color=color,","                 fontweight='bold' if sig else 'normal',","                 transform=ax.transAxes, va='center', ha='left')"," ","-    # ATE axis label","-    ax.text(ate_x + ate_max_w / 2, ate_top - 3 * bar_spacing - 0.01,","+    ax.text(ate_x + ate_max_w / 2, ate_top - 3 * bar_spacing - 0.005,","             'Causal Effect (ATE)', fontsize=7.5, color=TEXT_MID,","             transform=ax.transAxes, va='center', ha='center')"," ","     # Summary","-    ax.text(0.34, y_bot - 0.13, 'Only Llama shows causal effect',","+    ax.text(0.30, y_bot - 0.14, 'Only Llama shows causal effect',","             fontsize=7.5, color=TEXT_MID, fontstyle='italic',","             transform=ax.transAxes, va='center', ha='center')"," ","-    # ── \"Detection ≠ Decision\" tagline ──","-    tag_y = 0.035","-    # Subtle background pill","-    rbox(ax, 0.12, tag_y - 0.025, 0.76, 0.05,","-         fc='#F8F9FA', ec=BORDER_LIGHT, lw=0.6, rad=0.02, zorder=5)","+    # ── \"Detection ≠ Decision\" ──","+    tag_y = 0.045","+    rbox(ax, 0.10, tag_y - 0.03, 0.80, 0.06,","+         fc='#F8F9FA', ec='#DEE2E6', lw=0.6, rad=0.018, zorder=5)","     ax.text(0.50, tag_y, 'Detection  ≠  Decision',","             fontsize=11, color=TEXT_DARK, fontweight='bold',","-            transform=ax.transAxes, va='center', ha='center', zorder=6,","-            fontstyle='italic')","+            transform=ax.transAxes, va='center', ha='center', zorder=6)"," "," "," # ═══════════════════════════════════════════"]},{"oldStart":436,"oldLines":10,"newStart":445,"newLines":9,"lines":[" "," fig = plt.figure(figsize=(16, 5), dpi=300, facecolor=WHITE)"," ","-# Panel widths: 28% / 36% / 36%","-ax_a = fig.add_axes([0.01,  0.02, 0.28, 0.96])","-ax_b = fig.add_axes([0.32,  0.02, 0.32, 0.96])","-ax_c = fig.add_axes([0.66,  0.02, 0.33, 0.96])","+ax_a = fig.add_axes([0.01, 0.02, 0.28, 0.96])","+ax_b = fig.add_axes([0.315, 0.02, 0.33, 0.96])","+ax_c = fig.add_axes([0.66, 0.02, 0.33, 0.96])"," "," draw_panel_a(ax_a)"," draw_panel_b(ax_b)"]}],"originalFile":"#!/usr/bin/env python3\n\"\"\"Figure 1 Hero: Detection ≠ Decision — Cross-Lingual Knowledge Conflict.\n\nThree-panel figure (a) task illustration, (b) detection heatmaps, (c) causal steering.\nPublication quality for EMNLP 2026.\n\"\"\"\n\nimport matplotlib\nmatplotlib.use('Agg')\nimport matplotlib.pyplot as plt\nimport matplotlib.font_manager as fm\nimport matplotlib.colors as mcolors\nimport matplotlib.cm as cm\nfrom matplotlib.patches import FancyBboxPatch, FancyArrowPatch\nfrom matplotlib.collections import PatchCollection\nimport numpy as np\nimport os\n\n# ── Semantic Color Palette ──\nEN_BLUE      = '#2C5F8A'\nEN_BLUE_LT   = '#EBF5FB'\nEN_BLUE_MED  = '#AED6F1'\nZH_ORANGE    = '#D35400'\nZH_ORANGE_LT = '#FDF2E9'\nZH_ORANGE_MED= '#F5CBA7'\nTEAL         = '#0B6E4F'\nTEAL_LT      = '#D0ECE7'\nCAUSAL_RED   = '#C0392B'\nCAUSAL_RED_LT= '#FADBD8'\nNO_EFFECT    = '#D5D8DC'\nNO_EFFECT_DK = '#ABB2B9'\nTEXT_DARK    = '#2C3E50'\nTEXT_MID     = '#5D6D7E'\nTEXT_LIGHT   = '#95A5A6'\nBORDER_LIGHT = '#E5E8E8'\nWHITE        = '#FFFFFF'\n\n# ── CJK Fonts ──\n_CJK_PATHS = [\n    '/usr/share/fonts/opentype/noto/NotoSansCJK-Regular.ttc',\n    '/usr/share/fonts/opentype/noto/NotoSerifCJK-Regular.ttc',\n    '/usr/share/fonts/truetype/noto/NotoSansCJK-Regular.ttc',\n]\n_CJK_BOLD_PATHS = [\n    '/usr/share/fonts/opentype/noto/NotoSansCJK-Bold.ttc',\n    '/usr/share/fonts/opentype/noto/NotoSerifCJK-Bold.ttc',\n    '/usr/share/fonts/truetype/noto/NotoSansCJK-Bold.ttc',\n]\n\ndef _find_font(paths):\n    for p in paths:\n        if os.path.exists(p):\n            return p\n    return None\n\n_cjk_path = _find_font(_CJK_PATHS)\n_cjk_bold_path = _find_font(_CJK_BOLD_PATHS)\nCJK = fm.FontProperties(fname=_cjk_path, size=9) if _cjk_path else None\nCJK_B = fm.FontProperties(fname=_cjk_bold_path, size=10) if _cjk_bold_path else None\n\nplt.rcParams.update({\n    'font.family': 'serif',\n    'font.serif': ['Times New Roman', 'DejaVu Serif', 'Liberation Serif'],\n    'mathtext.fontset': 'dejavuserif',\n    'font.size': 9,\n    'axes.linewidth': 0,\n    'figure.facecolor': WHITE,\n    'axes.facecolor': WHITE,\n    'text.color': TEXT_DARK,\n})\n\n\n# ── Synthetic probe accuracy data (32 layers) ──\nnp.random.seed(42)\nlayers = np.arange(1, 33)\n\ndef make_probe_curve(peak_layer, peak_val, base_val=0.52, width=6):\n    curve = base_val + (peak_val - base_val) * np.exp(-0.5 * ((layers - peak_layer) / width) ** 2)\n    curve += np.random.normal(0, 0.012, len(layers))\n    return np.clip(curve, 0.50, 1.0)\n\nprobe_llama = make_probe_curve(18, 0.92, width=7)\nprobe_qwen  = make_probe_curve(16, 0.88, width=6)\nprobe_gemma = make_probe_curve(20, 0.85, width=8)\n\ncausal_llama = np.zeros(32)\ncausal_llama[12:16] = [0.35, 0.42, 0.38, 0.28]  # L13-L16 causal window\n\ncausal_qwen  = np.random.uniform(0.0, 0.04, 32)\ncausal_gemma = np.random.uniform(0.0, 0.03, 32)\n\n\n# ── Helper: rounded box ──\ndef rbox(ax, x, y, w, h, fc=WHITE, ec=BORDER_LIGHT, lw=0.7, rad=0.015,\n         alpha=1, zorder=2, transform=None):\n    t = transform or ax.transAxes\n    p = FancyBboxPatch((x, y), w, h,\n                       boxstyle=f'round,pad=0,rounding_size={rad}',\n                       fc=fc, ec=ec, lw=lw, alpha=alpha,\n                       transform=t, zorder=zorder, clip_on=False)\n    ax.add_patch(p)\n    return p\n\n\ndef draw_heatbar(ax, data, x_center, bar_width, cmap, vmin=0.5, vmax=1.0,\n                 n_layers=32, y_bot=0.18, y_top=0.88):\n    \"\"\"Draw a vertical heatmap bar representing layer-wise values.\"\"\"\n    layer_h = (y_top - y_bot) / n_layers\n    half_w = bar_width / 2\n    norm = mcolors.Normalize(vmin=vmin, vmax=vmax)\n\n    for i in range(n_layers):\n        yy = y_bot + i * layer_h\n        color = cmap(norm(data[i]))\n        rbox(ax, x_center - half_w, yy, bar_width, layer_h * 0.92,\n             fc=color, ec='none', lw=0, rad=0.002, zorder=3)\n\n    # Thin outer border\n    rbox(ax, x_center - half_w - 0.003, y_bot - 0.005,\n         bar_width + 0.006, y_top - y_bot + 0.01,\n         fc='none', ec=BORDER_LIGHT, lw=0.6, rad=0.008, zorder=4)\n\n\n# ═══════════════════════════════════════════\n# Panel (a): Cross-Lingual Knowledge Conflict\n# ═══════════════════════════════════════════\n\ndef draw_panel_a(ax):\n    ax.set_xlim(0, 1)\n    ax.set_ylim(0, 1)\n    ax.axis('off')\n\n    # Panel label\n    ax.text(0.02, 0.97, '(a)', fontsize=11, fontweight='bold', color=TEXT_DARK,\n            transform=ax.transAxes, va='top', ha='left')\n    ax.text(0.12, 0.97, 'Cross-Lingual Knowledge Conflict',\n            fontsize=10, color=TEXT_DARK, fontweight='bold',\n            transform=ax.transAxes, va='top', ha='left')\n\n    # Thin separator line under title\n    ax.plot([0.02, 0.98], [0.93, 0.93], color=BORDER_LIGHT, lw=0.8,\n            transform=ax.transAxes, zorder=1)\n\n    # Question\n    qy = 0.83\n    rbox(ax, 0.06, qy, 0.88, 0.065, fc='#F8F9FA', ec='#DEE2E6', lw=0.6, rad=0.012)\n    ax.text(0.50, qy + 0.033, 'Q: \"Where was Marie Curie born?\"',\n            fontsize=9, color=TEXT_DARK, fontweight='bold',\n            transform=ax.transAxes, va='center', ha='center')\n\n    # ── EN Context Card ──\n    ey, eh = 0.50, 0.27\n    # Left accent stripe\n    rbox(ax, 0.06, ey, 0.018, eh, fc=EN_BLUE, ec='none', lw=0, rad=0.004)\n    # Card body\n    rbox(ax, 0.078, ey, 0.86, eh, fc=EN_BLUE_LT, ec=EN_BLUE_MED, lw=0.6, rad=0.01)\n\n    ax.text(0.11, ey + eh * 0.82, 'EN Context', fontsize=8.5, color=EN_BLUE,\n            fontweight='bold', transform=ax.transAxes, va='center')\n    ax.text(0.11, ey + eh * 0.52, '\"Marie Curie was born in\\n  Warsaw, Poland...\"',\n            fontsize=8, color=TEXT_MID, transform=ax.transAxes, va='center',\n            linespacing=1.3)\n\n    # Answer arrow + label\n    ax.annotate('', xy=(0.72, ey + eh * 0.22), xytext=(0.62, ey + eh * 0.22),\n                arrowprops=dict(arrowstyle='->', color=EN_BLUE, lw=1.2,\n                                mutation_scale=10),\n                xycoords='axes fraction', textcoords='axes fraction')\n    ax.text(0.82, ey + eh * 0.25, 'Warsaw', fontsize=9.5, color=EN_BLUE,\n            fontweight='bold', transform=ax.transAxes, va='center', ha='center')\n    ax.text(0.82, ey + eh * 0.10, '(parametric)', fontsize=7, color=TEXT_LIGHT,\n            transform=ax.transAxes, va='center', ha='center')\n\n    # ── Conflict indicator ──\n    cy = 0.44\n    # Crossed arrows\n    ax.annotate('', xy=(0.58, cy), xytext=(0.42, cy + 0.04),\n                arrowprops=dict(arrowstyle='-', color='#E74C3C', lw=1.5, alpha=0.6),\n                xycoords='axes fraction', textcoords='axes fraction')\n    ax.annotate('', xy=(0.42, cy), xytext=(0.58, cy + 0.04),\n                arrowprops=dict(arrowstyle='-', color='#E74C3C', lw=1.5, alpha=0.6),\n                xycoords='axes fraction', textcoords='axes fraction')\n    ax.text(0.50, cy + 0.02, 'CONFLICT', fontsize=7, color='#E74C3C',\n            fontweight='bold', fontstyle='italic',\n            transform=ax.transAxes, va='center', ha='center',\n            bbox=dict(fc=WHITE, ec='none', pad=1.5, alpha=0.9))\n\n    # ── ZH Context Card ──\n    zy, zh = 0.11, 0.27\n    # Left accent stripe\n    rbox(ax, 0.06, zy, 0.018, zh, fc=ZH_ORANGE, ec='none', lw=0, rad=0.004)\n    # Card body\n    rbox(ax, 0.078, zy, 0.86, zh, fc=ZH_ORANGE_LT, ec=ZH_ORANGE_MED, lw=0.6, rad=0.01)\n\n    ax.text(0.11, zy + zh * 0.82, 'ZH Context', fontsize=8.5, color=ZH_ORANGE,\n            fontweight='bold', transform=ax.transAxes, va='center')\n\n    zh_text = '\"居里夫人出生于巴黎...\"'\n    fp = CJK if CJK else None\n    ax.text(0.11, zy + zh * 0.52, zh_text,\n            fontsize=8, color=TEXT_MID, transform=ax.transAxes, va='center',\n            fontproperties=fp, linespacing=1.3)\n\n    ax.annotate('', xy=(0.72, zy + zh * 0.22), xytext=(0.62, zy + zh * 0.22),\n                arrowprops=dict(arrowstyle='->', color=ZH_ORANGE, lw=1.2,\n                                mutation_scale=10),\n                xycoords='axes fraction', textcoords='axes fraction')\n\n    fp_b = CJK_B if CJK_B else None\n    ax.text(0.82, zy + zh * 0.25, '巴黎', fontsize=10, color=ZH_ORANGE,\n            fontweight='bold', transform=ax.transAxes, va='center', ha='center',\n            fontproperties=fp_b)\n    ax.text(0.82, zy + zh * 0.10, '(contextual)', fontsize=7, color=TEXT_LIGHT,\n            transform=ax.transAxes, va='center', ha='center')\n\n    # Source citation\n    ax.text(0.50, 0.03, 'ConflictQA (Xie et al., 2024)',\n            fontsize=7, color=TEXT_LIGHT, fontstyle='italic',\n            transform=ax.transAxes, va='center', ha='center')\n\n\n# ═══════════════════════════════════════════\n# Panel (b): Detection via Probing\n# ═══════════════════════════════════════════\n\ndef draw_panel_b(ax):\n    ax.set_xlim(0, 1)\n    ax.set_ylim(0, 1)\n    ax.axis('off')\n\n    # Panel label\n    ax.text(0.02, 0.97, '(b)', fontsize=11, fontweight='bold', color=TEXT_DARK,\n            transform=ax.transAxes, va='top', ha='left')\n    ax.text(0.12, 0.97, 'Detection via Probing',\n            fontsize=10, color=TEXT_DARK, fontweight='bold',\n            transform=ax.transAxes, va='top', ha='left')\n    ax.plot([0.02, 0.98], [0.93, 0.93], color=BORDER_LIGHT, lw=0.8,\n            transform=ax.transAxes, zorder=1)\n\n    # Teal colormap\n    cmap_teal = mcolors.LinearSegmentedColormap.from_list(\n        'teal_grad', [WHITE, TEAL_LT, TEAL])\n\n    y_bot, y_top = 0.20, 0.88\n    bar_w = 0.08\n    positions = [0.22, 0.48, 0.74]\n    model_names = ['Llama-3', 'Qwen-2.5', 'Gemma-2']\n    probes = [probe_llama, probe_qwen, probe_gemma]\n    peak_layers = [18, 16, 20]\n\n    for idx, (xc, name, data, pk) in enumerate(zip(positions, model_names, probes, peak_layers)):\n        draw_heatbar(ax, data, xc, bar_w, cmap_teal, vmin=0.50, vmax=0.95,\n                     y_bot=y_bot, y_top=y_top)\n\n        # Model name below\n        ax.text(xc, y_bot - 0.045, name, fontsize=8, color=TEXT_DARK,\n                fontweight='bold', transform=ax.transAxes, va='center', ha='center')\n\n        # Checkmark\n        ax.text(xc, y_bot - 0.085, '✓', fontsize=10, color=TEAL,\n                fontweight='bold', transform=ax.transAxes, va='center', ha='center')\n\n        # Peak annotation (only for first bar to avoid clutter)\n        if idx == 0:\n            pk_y = y_bot + (pk - 0.5) / 32 * (y_top - y_bot)\n            ax.annotate('detection\\npeak',\n                        xy=(xc + bar_w / 2 + 0.01, pk_y),\n                        xytext=(xc + bar_w / 2 + 0.08, pk_y + 0.04),\n                        fontsize=7.5, color=TEAL, fontweight='bold',\n                        transform=ax.transAxes, va='center', ha='left',\n                        linespacing=1.1,\n                        arrowprops=dict(arrowstyle='->', color=TEAL, lw=1.0,\n                                        connectionstyle='arc3,rad=-0.15',\n                                        mutation_scale=8))\n\n    # Layer labels on left\n    for ln, label in [(1, 'L1'), (8, 'L8'), (16, 'L16'), (24, 'L24'), (32, 'L32')]:\n        