wstyle='->', color=TEAL, lw=0.9,","-                                connectionstyle='arc3,rad=-0.15',","+                                connectionstyle='arc3,rad=-0.2',","                                 mutation_scale=8))"," ","-    # Layer labels on left","+    # Layer labels","     for ln, label in [(1, 'L1'), (8, 'L8'), (16, 'L16'), (24, 'L24'), (32, 'L32')]:","         yy = y_bot + (ln - 0.5) / 32 * (y_top - y_bot)","-        ax.text(0.07, yy, label, fontsize=7, color=TEXT_LIGHT,","+        ax.text(0.07, yy, label, fontsize=6.5, color=TEXT_LIGHT,","                 transform=ax.transAxes, va='center', ha='right')"," ","-    # Input / Output","-    ax.text(0.07, y_bot - 0.01, 'Input', fontsize=7, color=TEXT_LIGHT,","+    ax.text(0.07, y_bot - 0.015, 'Input', fontsize=6.5, color=TEXT_LIGHT,","             transform=ax.transAxes, va='top', ha='right')","-    ax.text(0.07, y_top + 0.01, 'Output', fontsize=7, color=TEXT_LIGHT,","+    ax.text(0.07, y_top + 0.015, 'Output', fontsize=6.5, color=TEXT_LIGHT,","             transform=ax.transAxes, va='bottom', ha='right')"," ","-    # Vertical colorbar","-    cb_x, cb_w = 0.88, 0.035","-    cb_bot, cb_top = y_bot + 0.10, y_bot + 0.55","+    # Compact colorbar","+    cb_x, cb_w = 0.90, 0.03","+    cb_bot, cb_top = y_bot + 0.15, y_bot + 0.50","     n_cb = 40","     for i in range(n_cb):","         frac = i / n_cb"]},{"oldStart":318,"oldLines":17,"newStart":296,"newLines":17,"lines":["             fc=color, ec='none', lw=0,","             transform=ax.transAxes, zorder=3, clip_on=False)","         ax.add_patch(rect)","-    rbox(ax, cb_x - 0.002, cb_bot - 0.002, cb_w + 0.004, cb_top - cb_bot + 0.004,","+    rbox(ax, cb_x - 0.001, cb_bot - 0.001, cb_w + 0.002, cb_top - cb_bot + 0.002,","          fc='none', ec='#CCD1D1', lw=0.4, rad=0.003, zorder=4)","-    ax.text(cb_x + cb_w / 2, cb_bot - 0.03, '0.50', fontsize=6, color=TEXT_LIGHT,","+    ax.text(cb_x + cb_w / 2, cb_bot - 0.025, '0.50', fontsize=6, color=TEXT_LIGHT,","      