AL_RED])"," ","     y_bot, y_top = 0.26, 0.88","-    bar_w = 0.07","+    bar_w = 0.075","     positions = [0.12, 0.30, 0.48]","     model_names = ['Llama-3', 'Qwen-2.5', 'Gemma-2']","     causals = [causal_llama, causal_qwen, causal_gemma]"]},{"oldStart":364,"oldLines":13,"newStart":341,"newLines":13,"lines":["         draw_heatbar(ax, data, xc, bar_w, cmap_causal, vmin=0.0, vmax=0.45,","                      y_bot=y_bot, y_top=y_top)"," ","-        ax.text(xc, y_bot - 0.04, name, fontsize=7, color=TEXT_DARK,","+        ax.text(xc, y_bot - 0.04, name, fontsize=7.5, color=TEXT_DARK,","                 fontweight='bold', transform=ax.transAxes, va='center', ha='center')"," ","         if eff:","-            draw_check(ax, xc, y_bot - 0.085, CAUSAL_RED, size=0.014)","+            draw_check(ax, xc, y_bot - 0.09, CAUSAL_RED, size=0.014)","         else:","-            draw_cross(ax, xc, y_bot - 0.085, NO_EFFECT_DK, size=0.012)","+            draw_cross(ax, xc, y_bot - 0.09, NO_EFFECT_DK, size=0.012)"," ","     # Layer labels","     for ln in [1, 13, 16, 32]:"]},{"oldStart":381,"oldLines":34,"newStart":358,"newLines":35,"lines":["                 transform=ax.transAxes, va='center', ha='right')"," ","     # Causal window bracket","-    l13_y = y_bot + (12.5) / 32 * (y_top - y_bot)","-    l16_y = y_bot + (15.5) / 32 * (y_top - y_bot)","+    l13_y = y_bot + 12.5 / 32 * (y_top - y_bot)","+    l16_y = y_bot + 15.5 / 32 * (y_top - y_bot)","     mid_y = (l13_y + l16_y) / 2","-    bx = 0.12 + bar_w / 2 + 0.02","-    ax.plot([bx, bx + 0.012, bx + 0.012, bx], [l13_y, l13_y, l16_y, l16_y],","-            color=CAUSAL_RED, lw=0.9, transform=ax.transAxes, zorder=5,","+    bx = positions[0] + bar_w / 2 + 0.018","+    ax.plot([bx, bx + 0.012, bx + 0.012, bx],","+            [l13_y, l13_y, l16_y, l16_y],","+            color=CAUSAL_RED, lw=1.0, transform=ax.transAxes, zorder=5,","             solid_capstyle='round')","-    ax.text(bx + 0.025, mid_y, 'causal\\nwindow', fontsize=6.5, color=CAUSAL_RED,","+    ax.text(bx + 0.022, mid_y, 'causal\\nwindow', fontsize=6.5, color=CAUSAL_RED,","             fontweight='bold', transform=ax.transAxes, va='center', ha='left',","             linespacing=1.0)"," ","     # ── ATE bars + p-values ──","-    ate_x = 0.60","-    ate_max_w = 0.26","+    ate_x = 0.62","+    ate_max_w = 0.24","     ate_data = [","         ('L13', 0.42, 'p < 0.001 ***', CAUSAL_RED, True),","         ('L16', 0.28, 'p = 0.005 **', CAUSAL_RED, True),","         ('L28', 0.03, 'p = 0.284 n.s.', NO_EFFECT_DK, False),","     ]"," ","-    bar_spacing = 0.065","+    bar_spacing = 0.07","     ate_top = 0.80","     for i, (layer, effect, pval, color, sig) in enumerate(ate_data):","         yy = ate_top - i * bar_spacing","         bw = max(effect / 0.45 * ate_max_w, 0.012)","-        bh = 0.022","+        bh = 0.024"," ","-        ax.text(ate_x - 0.02, yy, layer, fontsize=7.5, color=color,","+        ax.text(ate_x - 0.015, yy, layer, fontsize=7.5, color=color,","                 fontweight='bold' if sig else 'normal',","                 transform=ax.transAxes, va='center', ha='right')"," "]},{"oldStart":421,"oldLines":21,"newStart":399,"newLines":20,"lines":["                 fontweight='bold' if sig else 'normal',","                 transform=ax.transAxes, va='center', ha='left')"," ","-    ax.text(ate_x + ate_max_w / 2, ate_top - 3 * bar_spacing - 0.005,","+    ax.text(ate_x + ate_max_w * 0.45, ate_top - 3 * bar_spacing - 0.005,","             'Causal Effect (ATE)', fontsize=7.5, color=TEXT_MID,","             transform=ax.transAxes, va='center', ha='center')"," ","-    # Summary","-    ax.text(0.30, y_bot - 0.14, 'Only Llama shows causal effect',","+    ax.text(0.30, y_bot - 0.145, 'Only Llama shows causal effect',","             fontsize=7.5, color=TEXT_MID, fontstyle='italic',","             transform=ax.transAxes, va='center', ha='center')"," ","     # ── \"Detection ≠ Decision\" ──","-    tag_y = 0.045","-    rbox(ax, 0.10, tag_y - 0.03, 0.80, 0.06,","-         fc='#F8F9FA', ec='#DEE2E6', lw=0.6, rad=0.018, zorder=5)","+    tag_y = 0.05","+    rbox(ax, 0.12, tag_y - 0.032, 0.76, 0.065,","+         fc='#F8F9FA', ec='#DEE2E6', lw=0.5, rad=0.018, zorder=5)","     ax.text(0.50, tag_y, 'Detection  ≠  Decision',","-            fontsize=11, color=TEXT_DARK, fontweight='bold',","+            fontsize=11.5, color=TEXT_DARK, fontweight='bold',","             transform=ax.transAxes, va='center', ha='center', zorder=6)"," "," "]},{"oldStart":445,"oldLines":8,"newStart":422,"newLines":8,"lines":[" "," fig = plt.figure(figsize=(16, 5), dpi=300, facecolor=WHITE)"," ","-ax_a = fig.add_axes([0.01, 0.02, 0.28, 0.96])","-ax_b = fig.add_axes([0.315, 0.02, 0.33, 0.96])","+ax_a = fig.add_axes([0.01, 0.02, 0.27, 0.96])","+ax_b = fig.add_axes([0.31, 0.02, 0.33, 0.96])"," ax_c = fig.add_axes([0.66, 0.02, 0.33, 0.96])"," "," draw_panel_a(ax_a)"]}],"originalFile":"#!/usr/bin/env python3\n\"\"\"Figure 1 Hero: Detection ≠ Decision — Cross-Lingual Knowledge Conflict.\n\nThree-panel figure (a) task illustration, (b) detection heatmaps, (c) causal steering.\nPublication quality for EMNLP 2026. Iteration 2.\n\"\"\"\n\nimport matplotlib\nmatplotlib.use('Agg')\nimport matplotlib.pyplot as plt\nimport matplotlib.font_manager as fm\nimport matplotlib.colors as mcolors\nfrom matplotlib.patches import FancyBboxPatch\nimport numpy as np\nimport os\n\n# ── Semantic Color Palette ──\nEN_BLUE      = '#2C5F8A'\nEN_BLUE_LT   = '#EBF5FB'\nEN_BLUE_MED  = '#AED6F1'\nZH_ORANGE    = '#D35400'\nZH_ORANGE_LT = '#FDF2E9'\nZH_ORANGE_MED= '#F5CBA7'\nTEAL         = '#0B6E4F'\nTEAL_LT      = '#D0ECE7'\nCAUSAL_RED   = '#C0392B'\nCAUSAL_RED_LT= '#FADBD8'\nNO_EFFECT    = '#D5D8DC'\nNO_EFFECT_DK = '#ABB2B9'\nTEXT_DARK    = '#2C3E50'\nTEXT_MID     = '#5D6D7E'\nTEXT_LIGHT   = '#95A5A6'\nBORDER_LIGHT = '#E5E8E8'\nWHITE        = '#FFFFFF'\nCONFLICT_RED = '#E74C3C'\n\n# ── CJK Fonts ──\n_CJK_PATHS = [\n    '/usr/share/fonts/opentype/noto/NotoSansCJK-Regular.ttc',\n    '/usr/share/fonts/opentype/noto/NotoSerifCJK-Regular.ttc',\n    '/usr/share/fonts/truetype/noto/NotoSansCJK-Regular.ttc',\n]\n_CJK_BOLD_PATHS = [\n    '/usr/share/fonts/opentype/noto/NotoSansCJK-Bold.ttc',\n    '/usr/share/fonts/opentype/noto/NotoSerifCJK-Bold.ttc',\n    '/usr/share/fonts/truetype/noto/NotoSansCJK-Bold.ttc',\n]\n\ndef _find_font(paths):\n    for p in paths:\n        if os.path.exists(p):\n            return p\n    return None\n\n_cjk_path = _find_font(_CJK_PATHS)\n_cjk_bold_path = _find_font(_CJK_BOLD_PATHS)\nCJK = fm.FontProperties(fname=_cjk_path, size=9) if _cjk_path else None\nCJK_B = fm.FontProperties(fname=_cjk_bold_path, size=10) if _cjk_bold_path else None\n\n# Use sans-serif for symbol rendering\n_SYM_PATHS = [\n    '/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf',\n    '/usr/share/fonts/truetype/noto/NotoSans-Regular.ttf',\n]\n_sym_path = _find_font(_SYM_PATHS)\nSYM = fm.FontProperties(fname=_sym_path, size=10) if _sym_path else None\n\nplt.rcParams.update({\n    'font.family': 'serif',\n    'font.serif': ['Times New Roman', 'DejaVu Serif', 'Liberation Serif'],\n    'mathtext.fontset': 'dejavuserif',\n    'font.size': 9,\n    'axes.linewidth': 0,\n    'figure.facecolor': WHITE,\n    'axes.facecolor': WHITE,\n    'text.color': TEXT_DARK,\n})\n\n\n# ── Synthetic probe accuracy data (32 layers) ──\nnp.random.seed(42)\nlayers = np.arange(1, 33)\n\ndef make_probe_curve(peak_layer, peak_val, base_val=0.52, width=6):\n    curve = base_val + (peak_val - base_val) * np.exp(-0.5 * ((layers - peak_layer) / width) ** 2)\n    curve += np.random.normal(0, 0.012, len(layers))\n    return np.clip(curve, 0.50, 1.0)\n\nprobe_llama = make_probe_curve(18, 0.92, width=7)\nprobe_qwen  = make_probe_curve(16, 0.88, width=6)\nprobe_gemma = make_probe_curve(20, 0.85, width=8)\n\ncausal_llama = np.zeros(32)\ncausal_llama[12:16] = [0.35, 0.42, 0.38, 0.28]\n\ncausal_qwen  = np.random.uniform(0.0, 0.04, 32)\ncausal_gemma = np.random.uniform(0.0, 0.03, 32)\n\n\n# ── Helper: rounded box ──\ndef rbox(ax, x, y, w, h, fc=WHITE, ec=BORDER_LIGHT, lw=0.7, rad=0.015,\n         alpha=1, zorder=2):\n    p = FancyBboxPatch((x, y), w, h,\n                       boxstyle=f'round,pad=0,rounding_size={rad}',\n                       fc=fc, ec=ec, lw=lw, alpha=alpha,\n                       transform=ax.transAxes, zorder=zorder, clip_on=False)\n    ax.add_patch(p)\n    return p\n\n\ndef draw_heatbar(ax, data, x_center, bar_width, cmap, vmin=0.5, vmax=1.0,\n                 n_layers=32, y_bot=0.18, y_top=0.88):\n    \"\"\"Draw a seamless vertical heatmap bar.\"\"\"\n    layer_h = (y_top - y_bot) / n_layers\n    half_w = bar_width / 2\n    norm = mcolors.Normalize(vmin=vmin, vmax=vmax)\n\n    for i in range(n_layers):\n        yy = y_bot + i * layer_h\n        color = cmap(norm(data[i]))\n        # Use rectangle patches with NO gap\n        rect = FancyBboxPatch(\n            (x_center - half_w, yy), bar_width, layer_h + 0.001,\n            boxstyle='square,pad=0',\n            fc=color, ec='none', lw=0, alpha=1,\n            transform=ax.transAxes, zorder=3, clip_on=False)\n        ax.add_patch(rect)\n\n    # Outer border\n    rbox(ax, x_center - half_w - 0.002, y_bot - 0.002,\n         bar_width + 0.004, y_top - y_bot + 0.004,\n         fc='none', ec='#CCD1D1', lw=0.5, rad=0.006, zorder=4)\n\n\ndef draw_check(ax, x, y, color, size=0.018):\n    \"\"\"Draw a checkmark without relying on unicode glyphs.\"\"\"\n    dx, dy = size, size\n    xs = [x - dx * 0.6, x - dx * 0.1, x + dx * 0.7]\n    ys = [y + dy * 0.1, y - dy * 0.4, y + dy * 0.5]\n    ax.plot(xs, ys, color=color, lw=2.0, solid_capstyle='round',\n            solid_joinstyle='round', transform=ax.transAxes, zorder=6)\n\n\ndef draw_cross(ax, x, y, color, size=0.015):\n    \"\"\"Draw an X mark without relying on unicode glyphs.\"\"\"\n    dx, dy = size, size\n    ax.plot([x - dx, x + dx], [y - dy, y + dy], color=color, lw=1.8,\n            solid_capstyle='round', transform=ax.transAxes, zorder=6)\n    ax.plot([x - dx, x + dx], [y + dy, y - dy], color=color, lw=1.8,\n            solid_capstyle='round', transform=ax.transAxes, zorder=6)\n\n\n# ═══════════════════════════════════════════\n# Panel (a): Cross-Lingual Knowledge Conflict\n# ═══════════════════════════════════════════\n\ndef draw_panel_a(ax):\n    ax.set_xlim(0, 1)\n    ax.set_ylim(0, 1)\n    ax.axis('off')\n\n    # Panel label\n    ax.text(0.03, 0.96, '(a)', fontsize=11, fontweight='bold', color=TEXT_DARK,\n            transform=ax.transAxes, va='top', ha='left')\n    ax.text(0.14, 0.96, 'Cross-Lingual Knowledge Conflict',\n            fontsize=9.5, color=TEXT_DARK, fontweight='bold',\n            transform=ax.transAxes, va='top', ha='left')\n\n    # Question\n    qy = 0.83\n    rbox(ax, 0.05, qy, 0.90, 0.07, fc='#F8F9FA', ec='#DEE2E6', lw=0.6, rad=0.012)\n    ax.text(0.50, qy + 0.035, 'Q: \"Where was Marie Curie born?\"',\n            fontsize=9.5, color=TEXT_DARK, fontweight='bold',\n            transform=ax.transAxes, va='center', ha='center')\n\n    # ── EN Context Card ──\n    ey, eh = 0.50, 0.28\n    rbox(ax, 0.05, ey, 0.022, eh, fc=EN_BLUE, ec='none', lw=0, rad=0.005)\n    rbox(ax, 0.072, ey, 0.87, eh, fc=EN_BLUE_LT, ec=EN_BLUE_MED, lw=0.6, rad=0.01)\n\n    ax.text(0.11, ey + eh * 0.82, 'EN Context', fontsize=8.5, color=EN_BLUE,\n            fontweight='bold', transform=ax.transAxes, va='center')\n    ax.text(0.11, ey + eh * 0.50, '\"Marie Curie was born in\\n  Warsaw, Poland...\"',\n            fontsize=8, color=TEXT_MID, transform=ax.transAxes, va='center',\n            linespacing=1.35)\n\n    ax.annotate('', xy=(0.73, ey + eh * 0.22), xytext=(0.62, ey + eh * 0.22),\n                arrowprops=dict(arrowstyle='->', color=EN_BLUE, lw=1.2,\n                                mutation_scale=10),\n                xycoords='axes fraction', textcoords='axes fraction')\n    ax.text(0.83, ey + eh * 0.25, 'Warsaw', fontsize=10, color=EN_BLUE,\n            fontweight='bold', transform=ax.transAxe